DHCP = {"id": "dhcp", "objective": "5.5", "area": "Networking", "title": "DHCP explained: how devices get an address, and what to check when it fails",
        "symptoms": ["Device shows a 169.254.x.x address", "Connected to Wi-Fi or cable but 'no internet'", "Two devices fighting over one address", "Printers or servers keep changing address"],
        "causes": ["DHCP server or router is down or out of free addresses", "Lease range too small, or leases too long for a busy guest network", "A second router handing out addresses by mistake", "Cable, switch or Wi-Fi problem stopping the request from reaching the server", "A device set to a static address that overlaps the DHCP range"],
        "steps": ["Know the four-step exchange: the device broadcasts a Discover, a server answers with an Offer, the device sends a Request to accept it, and the server confirms with an Acknowledgment (often remembered as DORA).",
                  "A lease is an address loaned for a set time. The device tries to renew before it expires; after it lapses the address can go to another device.", "DHCP hands out more than the address: subnet mask, default gateway (the router), DNS servers, and sometimes a time server or domain name.",
                  "Check the device: run ipconfig /all and look at the address, gateway, DNS and 'DHCP Server'. A 169.254 address means no server answered.", "Try ipconfig /release then ipconfig /renew. If it still fails, test with another device on the same cable or Wi-Fi.",
                  "Check the server or router: is DHCP on, is the range big enough for the number of devices, and does the lease table show free addresses? Shorten lease times on busy guest networks.", "Unplug any extra router that is not meant to give out addresses (a rogue DHCP server).",
                  "Use DHCP for laptops and phones; give servers, printers and network gear a static address outside the DHCP range, or a DHCP reservation, so they never move."],
        "tools": ["Command prompt", "Router or DHCP server admin page", "A second device to compare"], "safety": "Write down current settings before changing the router, and do not change a production DHCP scope in business hours.",
        "escalate": "No address on any device and the DHCP server is healthy: check the switch, VLAN and any DHCP relay settings with whoever manages the network."}
GUIDES.append(DHCP)
from app.services import it_repair_electronics, it_repair_phones, it_repair_software, it_repair_vehicle_network, it_repair_more, it_repair_models, it_repair_home  # noqa: E402
for _m in (it_repair_phones, it_repair_software, it_repair_electronics, it_repair_vehicle_network, it_repair_more, it_repair_models, it_repair_home):
    GUIDES.extend(_m.GUIDES)


def sheet() -> dict:
    areas = sorted({g["area"] for g in GUIDES})
    return {"method": [{"step": i + 1, "name": n, "what": w} for i, (n, w) in enumerate(METHOD)], "safety": SAFETY, "areas": areas, "guides": GUIDES, "toolkit": TOOLKIT,
            "note": "Written for this dashboard as practical procedures; the computer guides are mapped to the CompTIA A+ 220-1201 troubleshooting domain. Always follow the maker's manual for your exact model. Some jobs are not safe to do yourself: mains wiring, gas, microwave ovens, the high-voltage parts of EVs and sealed cooling systems belong to licensed technicians."}
